#include <d3dcompiler.h>
#include <wrl/client.h>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
using Microsoft::WRL::ComPtr;
using Clock=std::chrono::steady_clock;
static double ms(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::milli>(b-a).count();}
static void check(HRESULT hr){if(FAILED(hr))throw std::runtime_error("HRESULT "+std::to_string(uint32_t(hr)));}
static std::vector<char> read(const wchar_t* path){std::ifstream f(path,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("open file");auto n=f.tellg();if(n<0||n>16*1024*1024)throw std::runtime_error("file size");std::vector<char> data(size_t(n),0);f.seekg(0);f.read(data.data(),n);if(!f)throw std::runtime_error("read file");return data;}
static ComPtr<ID3D12Resource> buffer(ID3D12Device* d,uint64_t n,D3D12_HEAP_TYPE type,D3D12_RESOURCE_STATES state,bool uav=false){D3D12_HEAP_PROPERTIES h{};h.Type=type;D3D12_RESOURCE_DESC r{};r.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;r.Width=n;r.Height=1;r.DepthOrArraySize=1;r.MipLevels=1;r.SampleDesc.Count=1;r.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;r.Flags=uav?D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS:D3D12_RESOURCE_FLAG_NONE;ComPtr<ID3D12Resource> out;check(d->CreateCommittedResource(&h,D3D12_HEAP_FLAG_NONE,&r,state,nullptr,IID_PPV_ARGS(&out)));return out;}
static void transition(ID3D12GraphicsCommandList* c,ID3D12Resource* r,D3D12_RESOURCE_STATES a,D3D12_RESOURCE_STATES b){D3D12_RESOURCE_BARRIER x{};x.Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;x.Transition={r,D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES,a,b};c->ResourceBarrier(1,&x);}
int wmain(int argc,wchar_t** argv){try{
 if(argc!=8&&argc!=9){std::cerr<<"shader input expected count input_words output_words csv [gather.bin]\n";return 2;}
 auto input=read(argv[2]),expected=read(argv[3]);uint32_t count=std::stoul(argv[4]),inWords=std::stoul(argv[5]),outWords=std::stoul(argv[6]);
 if(!count||count>65536||!inWords||inWords>64||!outWords||outWords>64||input.size()!=uint64_t(count)*inWords*4||expected.size()!=uint64_t(count)*outWords*4)throw std::runtime_error("shape/size mismatch");
 std::vector<char> gather;std::vector<int32_t> gatherDesc;size_t sharedAt=0,rowsAt=0;uint32_t gatherStride=0;
 if(argc==9){gather=read(argv[8]);if(gather.size()<24||memcmp(gather.data(),"AIRG",4))throw std::runtime_error("gather magic");uint32_t h[5];memcpy(h,gather.data()+4,20);if(h[0]!=1||h[1]!=count||h[2]<4||h[2]>4096||h[3]!=inWords||h[4]>inWords)throw std::runtime_error("gather shape");gatherStride=h[2];sharedAt=24+size_t(inWords)*4;rowsAt=sharedAt+size_t(h[4])*4;if(gather.size()!=rowsAt+uint64_t(count)*gatherStride)throw std::runtime_error("gather size");for(uint32_t j=0;j<inWords;++j){int32_t slot;memcpy(&slot,gather.data()+24+j*4,4);if((slot>=0&&uint64_t(slot)+4>gatherStride)||(slot<0&&uint64_t(-1LL-slot)>=h[4]))throw std::runtime_error("gather slot");gatherDesc.push_back(slot);}}
 ComPtr<IDXGIFactory6> factory;check(CreateDXGIFactory2(0,IID_PPV_ARGS(&factory)));ComPtr<ID3D12Device> d;
 for(UINT i=0;;++i){ComPtr<IDXGIAdapter1> a;if(factory->EnumAdapterByGpuPreference(i,DXGI_GPU_PREFERENCE_HIGH_PERFORMANCE,IID_PPV_ARGS(&a))==DXGI_ERROR_NOT_FOUND)break;DXGI_ADAPTER_DESC1 desc{};a->GetDesc1(&desc);if(!(desc.Flags&DXGI_ADAPTER_FLAG_SOFTWARE)&&SUCCEEDED(D3D12CreateDevice(a.Get(),D3D_FEATURE_LEVEL_11_0,IID_PPV_ARGS(&d)))){std::wcout<<L"adapter="<<desc.Description<<L"\n";break;}}
 if(!d)throw std::runtime_error("hardware D3D12 unavailable");
 ComPtr<ID3DBlob> shader,error;auto hr=D3DCompileFromFile(argv[1],nullptr,D3D_COMPILE_STANDARD_FILE_INCLUDE,"main","cs_5_1",D3DCOMPILE_IEEE_STRICTNESS|D3DCOMPILE_ENABLE_STRICTNESS|D3DCOMPILE_OPTIMIZATION_LEVEL3,0,&shader,&error);if(FAILED(hr)&&error)std::cerr<<(char*)error->GetBufferPointer()<<'\n';check(hr);
 D3D12_ROOT_PARAMETER p[3]{};p[0].ParameterType=D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;p[0].Constants={0,0,1};p[1].ParameterType=D3D12_ROOT_PARAMETER_TYPE_SRV;p[1].Descriptor.ShaderRegister=0;p[2].ParameterType=D3D12_ROOT_PARAMETER_TYPE_UAV;p[2].Descriptor.ShaderRegister=0;D3D12_ROOT_SIGNATURE_DESC rd{};rd.NumParameters=3;rd.pParameters=p;ComPtr<ID3DBlob> rootBlob,rootError;check(D3D12SerializeRootSignature(&rd,D3D_ROOT_SIGNATURE_VERSION_1,&rootBlob,&rootError));ComPtr<ID3D12RootSignature> root;check(d->CreateRootSignature(0,rootBlob->GetBufferPointer(),rootBlob->GetBufferSize(),IID_PPV_ARGS(&root)));
 D3D12_COMPUTE_PIPELINE_STATE_DESC ps{};ps.pRootSignature=root.Get();ps.CS={shader->GetBufferPointer(),shader->GetBufferSize()};ComPtr<ID3D12PipelineState> pipeline;check(d->CreateComputePipelineState(&ps,IID_PPV_ARGS(&pipeline)));
 D3D12_COMMAND_QUEUE_DESC qd{};ComPtr<ID3D12CommandQueue> q;check(d->CreateCommandQueue(&qd,IID_PPV_ARGS(&q)));UINT64 frequency{};check(q->GetTimestampFrequency(&frequency));ComPtr<ID3D12CommandAllocator> alloc;check(d->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT,IID_PPV_ARGS(&alloc)));ComPtr<ID3D12GraphicsCommandList> cmd;check(d->CreateCommandList(0,D3D12_COMMAND_LIST_TYPE_DIRECT,alloc.Get(),nullptr,IID_PPV_ARGS(&cmd)));check(cmd->Close());ComPtr<ID3D12Fence> fence;check(d->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(&fence)));HANDLE event=CreateEventW(nullptr,FALSE,FALSE,nullptr);if(!event)throw std::runtime_error("event");
 auto upload=buffer(d.Get(),input.size(),D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ);auto source=buffer(d.Get(),input.size(),D3D12_HEAP_TYPE_DEFAULT,D3D12_RESOURCE_STATE_COPY_DEST);auto result=buffer(d.Get(),expected.size(),D3D12_HEAP_TYPE_DEFAULT,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,true);auto back=buffer(d.Get(),expected.size(),D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);auto times=buffer(d.Get(),4*sizeof(UINT64),D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);D3D12_QUERY_HEAP_DESC hd{};hd.Type=D3D12_QUERY_HEAP_TYPE_TIMESTAMP;hd.Count=4;ComPtr<ID3D12QueryHeap> query;check(d->CreateQueryHeap(&hd,IID_PPV_ARGS(&query)));char* up{};char* got{};UINT64* ticks{};D3D12_RANGE empty{};check(upload->Map(0,&empty,(void**)&up));check(back->Map(0,nullptr,(void**)&got));check(times->Map(0,nullptr,(void**)&ticks));
 std::ofstream csv(argv[7]);csv<<std::setprecision(10)<<"iteration,count,prep_ms,record_ms,submit_ms,wait_ms,consume_ms,full_ms,gpu_upload_ms,gpu_dispatch_ms,gpu_return_ms,validated,mismatch_words\n";
 std::vector<char> consumed(expected.size());UINT64 signal=0;for(int iteration=-1;iteration<20;++iteration){auto t0=Clock::now();if(gather.empty())memcpy(up,input.data(),input.size());else for(uint32_t i=0;i<count;++i)for(uint32_t j=0;j<inWords;++j){int32_t slot=gatherDesc[j];const char* word=slot>=0?gather.data()+rowsAt+size_t(i)*gatherStride+slot:gather.data()+sharedAt+size_t(-1LL-slot)*4;memcpy(up+(size_t(i)*inWords+j)*4,word,4);}auto t1=Clock::now();check(alloc->Reset());check(cmd->Reset(alloc.Get(),pipeline.Get()));cmd->SetComputeRootSignature(root.Get());cmd->SetComputeRoot32BitConstant(0,count,0);cmd->SetComputeRootShaderResourceView(1,source->GetGPUVirtualAddress());cmd->SetComputeRootUnorderedAccessView(2,result->GetGPUVirtualAddress());cmd->EndQuery(query.Get(),D3D12_QUERY_TYPE_TIMESTAMP,0);if(iteration!=-1)transition(cmd.Get(),source.Get(),D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,D3D12_RESOURCE_STATE_COPY_DEST);cmd->CopyBufferRegion(source.Get(),0,upload.Get(),0,input.size());transition(cmd.Get(),source.Get(),D3D12_RESOURCE_STATE_COPY_DEST,D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);cmd->EndQuery(query.Get(),D3D12_QUERY_TYPE_TIMESTAMP,1);if(iteration!=-1)transition(cmd.Get(),result.Get(),D3D12_RESOURCE_STATE_COPY_SOURCE,D3D12_RESOURCE_STATE_UNORDERED_ACCESS);cmd->Dispatch((count+63)/64,1,1);cmd->EndQuery(query.Get(),D3D12_QUERY_TYPE_TIMESTAMP,2);transition(cmd.Get(),result.Get(),D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE);cmd->CopyBufferRegion(back.Get(),0,result.Get(),0,expected.size());cmd->EndQuery(query.Get(),D3D12_QUERY_TYPE_TIMESTAMP,3);cmd->ResolveQueryData(query.Get(),D3D12_QUERY_TYPE_TIMESTAMP,0,4,times.Get(),0);check(cmd->Close());auto t2=Clock::now();ID3D12CommandList* list=cmd.Get();q->ExecuteCommandLists(1,&list);check(q->Signal(fence.Get(),++signal));auto t3=Clock::now();if(fence->GetCompletedValue()<signal){check(fence->SetEventOnCompletion(signal,event));if(WaitForSingleObject(event,15000)!=WAIT_OBJECT_0)throw std::runtime_error("GPU timeout");}auto t4=Clock::now();check(d->GetDeviceRemovedReason());memcpy(consumed.data(),got,expected.size());auto t5=Clock::now();bool validated=(iteration==-1||iteration==19);size_t mismatch=0;if(validated)for(size_t i=0;i<expected.size();i+=4)mismatch+=memcmp(consumed.data()+i,expected.data()+i,4)!=0;auto gpu=[&](int a,int b){return double(ticks[b]-ticks[a])*1000/double(frequency);};csv<<iteration<<','<<count<<','<<ms(t0,t1)<<','<<ms(t1,t2)<<','<<ms(t2,t3)<<','<<ms(t3,t4)<<','<<ms(t4,t5)<<','<<ms(t0,t5)<<','<<gpu(0,1)<<','<<gpu(1,2)<<','<<gpu(2,3)<<','<<validated<<','<<mismatch<<'\n';csv.flush();if(mismatch){std::wstring dumpPath=std::wstring(argv[7])+L".actual-output.bin";std::ofstream dump(dumpPath,std::ios::binary);dump.write(consumed.data(),consumed.size());dump.close();std::cerr<<"mismatch_words="<<mismatch<<" actual_output=<csv>.actual-output.bin first:";size_t shown=0;for(size_t j=0;j<expected.size()&&shown<24;j+=4)if(memcmp(consumed.data()+j,expected.data()+j,4)!=0){uint32_t actualWord=0,expectedWord=0;memcpy(&actualWord,consumed.data()+j,4);memcpy(&expectedWord,expected.data()+j,4);std::cerr<<" ["<<j/4<<":"<<std::hex<<actualWord<<"!="<<expectedWord<<std::dec<<"]";++shown;}std::cerr<<'\n';throw std::runtime_error("captured output mismatch");}}
 CloseHandle(event);std::cout<<"captured_outputs_exact=1 live_replacement=0 original_cpu_cost_unknown=1\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
